-- HG shared platform migration (schema: lms)
-- Source: lms-hg/supabase/migrations/20260927135348_phase1_scoped_roles.sql
-- Generated by platform/tools/convert.py: references to the public schema were
-- rewritten to `lms`; private schemas renamed app_private -> lms_private.
-- Edit the source app's migration history only until the cutover; after that, edit here.

SET search_path TO lms, extensions;

-- Forward-only role transition. Run atomically with the matching application release.
BEGIN;
LOCK TABLE lms.users IN ACCESS EXCLUSIVE MODE;
ALTER TABLE lms.users DROP CONSTRAINT users_role_check;
UPDATE lms.users SET role = CASE role
  WHEN 'learner' THEN 'user' WHEN 'teacher' THEN 'admin'
  WHEN 'admin' THEN 'super_admin' ELSE role END;
ALTER TABLE lms.users ALTER COLUMN role SET DEFAULT 'user';
ALTER TABLE lms.users ADD CONSTRAINT users_role_check
  CHECK (role IN ('user', 'admin', 'super_admin'));

CREATE OR REPLACE FUNCTION lms.is_super_admin() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = lms AS $$
  SELECT EXISTS (SELECT 1 FROM lms.users WHERE id = auth.uid()
    AND role = 'super_admin' AND is_active AND deleted_at IS NULL);
$$;
REVOKE ALL ON FUNCTION lms.is_super_admin() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION lms.is_super_admin() TO authenticated;

-- Preserve EVERY existing full-admin policy before broadening is_admin().
-- pg_policies expressions retain all predicates, commands, roles and column grants.
DO $migration$
DECLARE p record; statement text;
BEGIN
  FOR p IN SELECT * FROM pg_policies WHERE schemaname IN ('lms', 'storage')
    AND (coalesce(qual, '') LIKE '%is_admin()%' OR coalesce(with_check, '') LIKE '%is_admin()%')
  LOOP
    statement := format('ALTER POLICY %I ON %I.%I', p.policyname, p.schemaname, p.tablename);
    IF p.qual IS NOT NULL THEN
      statement := statement || ' USING (' || replace(p.qual, 'is_admin()', 'is_super_admin()') || ')';
    END IF;
    IF p.with_check IS NOT NULL THEN
      statement := statement || ' WITH CHECK (' || replace(p.with_check, 'is_admin()', 'is_super_admin()') || ')';
    END IF;
    EXECUTE statement;
  END LOOP;
END;
$migration$;

CREATE OR REPLACE FUNCTION lms.is_admin() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = lms AS $$
  SELECT EXISTS (SELECT 1 FROM lms.users WHERE id = auth.uid()
    AND role IN ('admin', 'super_admin') AND is_active AND deleted_at IS NULL);
$$;
-- Compatibility helper for existing assignment policies; no global privileges.
CREATE OR REPLACE FUNCTION lms.is_teacher() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = lms AS $$
  SELECT lms.is_admin();
$$;

CREATE TABLE lms.admin_permissions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES lms.users(id) ON DELETE CASCADE,
  permission text NOT NULL CHECK (permission IN ('manage_sessions', 'view_session_tracking',
    'view_analytics', 'export_analytics', 'manage_curriculum', 'manage_users')),
  granted_by uuid NOT NULL REFERENCES lms.users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, permission)
);
CREATE INDEX admin_permissions_granted_by_idx ON lms.admin_permissions(granted_by);
CREATE TABLE lms.module_teaching_permissions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES lms.users(id) ON DELETE CASCADE,
  module_id uuid NOT NULL REFERENCES lms.modules(id) ON DELETE CASCADE,
  granted_by uuid NOT NULL REFERENCES lms.users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, module_id)
);
CREATE INDEX module_teaching_permissions_module_idx ON lms.module_teaching_permissions(module_id);
CREATE INDEX module_teaching_permissions_granted_by_idx ON lms.module_teaching_permissions(granted_by);

CREATE OR REPLACE FUNCTION lms.has_admin_permission(requested_permission text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = lms AS $$
  SELECT lms.is_super_admin() OR (lms.is_admin() AND EXISTS (
    SELECT 1 FROM lms.admin_permissions WHERE user_id = auth.uid() AND permission = requested_permission));
$$;
CREATE OR REPLACE FUNCTION lms.can_teach_module(target_module_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = lms AS $$
  SELECT lms.is_super_admin() OR (lms.is_admin() AND EXISTS (
    SELECT 1 FROM lms.module_teaching_permissions WHERE user_id = auth.uid() AND module_id = target_module_id));
$$;
REVOKE ALL ON FUNCTION lms.has_admin_permission(text), lms.can_teach_module(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION lms.has_admin_permission(text), lms.can_teach_module(uuid) TO authenticated;

-- Trigger validates recipients even for service-role writes. Serialize against demotion.
CREATE FUNCTION lms.validate_admin_grant() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = lms AS $$
BEGIN
  PERFORM 1 FROM lms.users WHERE id = NEW.user_id
    AND role IN ('admin', 'super_admin') AND is_active AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Permission recipient must be an active Admin'; END IF;
  IF NOT EXISTS (SELECT 1 FROM lms.users WHERE id = NEW.granted_by
    AND role = 'super_admin' AND is_active AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Permissions must be granted by an active Super Admin';
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION lms.validate_admin_grant() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER validate_admin_permission BEFORE INSERT OR UPDATE ON lms.admin_permissions
  FOR EACH ROW EXECUTE FUNCTION lms.validate_admin_grant();
CREATE TRIGGER validate_module_permission BEFORE INSERT OR UPDATE ON lms.module_teaching_permissions
  FOR EACH ROW EXECUTE FUNCTION lms.validate_admin_grant();

CREATE FUNCTION lms.clear_revoked_admin_grants() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = lms AS $$
BEGIN
  IF NEW.role <> OLD.role OR NOT NEW.is_active OR NEW.deleted_at IS NOT NULL THEN
    DELETE FROM lms.admin_permissions WHERE user_id = NEW.id;
    DELETE FROM lms.module_teaching_permissions WHERE user_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION lms.clear_revoked_admin_grants() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER clear_revoked_admin_grants AFTER UPDATE OF role, is_active, deleted_at ON lms.users
  FOR EACH ROW EXECUTE FUNCTION lms.clear_revoked_admin_grants();

ALTER TABLE lms.admin_permissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE lms.module_teaching_permissions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON lms.admin_permissions, lms.module_teaching_permissions FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON lms.admin_permissions, lms.module_teaching_permissions TO authenticated;
GRANT ALL ON lms.admin_permissions, lms.module_teaching_permissions TO service_role;
CREATE POLICY "permissions: read own" ON lms.admin_permissions FOR SELECT TO authenticated
  USING (user_id = auth.uid() AND lms.is_admin());
CREATE POLICY "permissions: super admin manage" ON lms.admin_permissions TO authenticated
  USING (lms.is_super_admin()) WITH CHECK (lms.is_super_admin() AND granted_by = auth.uid());
CREATE POLICY "teaching: read own" ON lms.module_teaching_permissions FOR SELECT TO authenticated
  USING (user_id = auth.uid() AND lms.is_admin());
CREATE POLICY "teaching: super admin manage" ON lms.module_teaching_permissions TO authenticated
  USING (lms.is_super_admin()) WITH CHECK (lms.is_super_admin() AND granted_by = auth.uid());

-- No automatic permission backfill: former teachers receive only explicit grants.
-- Existing assignments survive, but module operations require a teaching grant.
DROP POLICY IF EXISTS "progress: teacher assigned" ON lms.learner_progress;
CREATE POLICY "progress: teacher assigned" ON lms.learner_progress FOR SELECT TO authenticated
  USING (lms.can_teach_module(module_id) AND
    (lms.is_assigned_teacher(learner_id) OR teacher_id = auth.uid()));

DROP POLICY IF EXISTS "events: teacher manage assigned" ON lms.events;
CREATE POLICY "events: scoped admin manage" ON lms.events TO authenticated
  USING (lms.has_admin_permission('manage_sessions') AND lms.can_teach_module(module_id)
    AND deleted_at IS NULL AND (created_by = auth.uid() OR teacher_id = auth.uid()))
  WITH CHECK (lms.has_admin_permission('manage_sessions') AND lms.can_teach_module(module_id)
    AND (created_by = auth.uid() OR teacher_id = auth.uid()));
CREATE OR REPLACE FUNCTION lms.is_event_manager(target_event_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = lms AS $$
  SELECT lms.is_super_admin() OR EXISTS (SELECT 1 FROM lms.events WHERE id = target_event_id
    AND deleted_at IS NULL AND (created_by = auth.uid() OR teacher_id = auth.uid())
    AND lms.has_admin_permission('manage_sessions') AND lms.can_teach_module(module_id));
$$;

-- Delegated curriculum writes still run through RLS and the existing column grants.
CREATE POLICY "modules: curriculum permission" ON lms.modules TO authenticated
  USING (lms.has_admin_permission('manage_curriculum'))
  WITH CHECK (lms.has_admin_permission('manage_curriculum'));
CREATE POLICY "module_versions: curriculum permission" ON lms.module_versions TO authenticated
  USING (lms.has_admin_permission('manage_curriculum'))
  WITH CHECK (lms.has_admin_permission('manage_curriculum'));
CREATE POLICY "categories: curriculum permission" ON lms.categories TO authenticated
  USING (lms.has_admin_permission('manage_curriculum'))
  WITH CHECK (lms.has_admin_permission('manage_curriculum'));
CREATE POLICY "storage: curriculum manage" ON storage.objects TO authenticated
  USING (bucket_id = 'study-notes' AND lms.has_admin_permission('manage_curriculum'))
  WITH CHECK (bucket_id = 'study-notes' AND name LIKE 'modules/%' AND lms.has_admin_permission('manage_curriculum'));
CREATE POLICY "users: delegated learner management" ON lms.users FOR SELECT TO authenticated
  USING (role = 'user' AND lms.has_admin_permission('manage_users'));

CREATE OR REPLACE FUNCTION lms.handle_new_user()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
BEGIN
  IF NEW.email IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.email_confirmed_at IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO lms.users (id, email, full_name, role)
  VALUES (
    NEW.id,
    NEW.email,
    NULLIF(BTRIM(COALESCE(NEW.raw_user_meta_data->>'full_name', '')), ''),
    'user'
  )
  ON CONFLICT (id) DO UPDATE
    SET email = EXCLUDED.email,
        full_name = COALESCE(lms.users.full_name, EXCLUDED.full_name);

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'handle_new_user failed for user %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION lms.validate_teacher_reference()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
BEGIN
  IF TG_TABLE_NAME = 'teacher_assignments' THEN
    IF NOT EXISTS (
      SELECT 1 FROM lms.users
      WHERE id = NEW.teacher_id
        AND role IN ('admin', 'super_admin')
        AND is_active = TRUE
        AND deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'teacher_assignments.teacher_id must reference an active teacher';
    END IF;
  ELSIF TG_TABLE_NAME = 'learner_progress' AND NEW.teacher_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM lms.users
      WHERE id = NEW.teacher_id
        AND role IN ('admin', 'super_admin')
        AND is_active = TRUE
        AND deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'learner_progress.teacher_id must reference an active teacher/admin';
    END IF;
  ELSIF TG_TABLE_NAME = 'events' AND NEW.teacher_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM lms.users
      WHERE id = NEW.teacher_id
        AND role IN ('admin', 'super_admin')
        AND is_active = TRUE
        AND deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'events.teacher_id must reference an active teacher/admin';
    END IF;
  END IF;

  IF TG_TABLE_NAME IN ('learner_progress', 'events') AND NEW.teacher_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM lms.users WHERE id = NEW.teacher_id AND role = 'super_admin')
      AND NOT EXISTS (SELECT 1 FROM lms.module_teaching_permissions
        WHERE user_id = NEW.teacher_id AND module_id = NEW.module_id) THEN
      RAISE EXCEPTION 'Selected Admin does not have teaching permission for this module';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION lms.log_activity_for_user(
  target_user_id UUID,
  activity activity_event,
  target_entity_type TEXT DEFAULT NULL,
  target_entity_id UUID DEFAULT NULL,
  activity_metadata JSONB DEFAULT '{}'::JSONB
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
DECLARE
  inserted_id UUID;
BEGIN
  IF NOT lms.is_active_app_user(auth.uid()) THEN
    RAISE EXCEPTION 'inactive or unauthenticated user cannot log activity';
  END IF;

  IF target_user_id <> auth.uid()
     AND NOT lms.is_super_admin()
     AND NOT lms.is_assigned_teacher(target_user_id) THEN
    RAISE EXCEPTION 'not authorized to log activity for target user';
  END IF;

  INSERT INTO lms.activity_logs (
    user_id,
    event,
    entity_type,
    entity_id,
    metadata
  )
  VALUES (
    target_user_id,
    activity,
    target_entity_type,
    target_entity_id,
    COALESCE(activity_metadata, '{}'::JSONB)
  )
  RETURNING id INTO inserted_id;

  RETURN inserted_id;
END;
$$;
DROP TRIGGER validate_learner_progress_teacher ON lms.learner_progress;
CREATE TRIGGER validate_learner_progress_teacher BEFORE INSERT OR UPDATE OF teacher_id, module_id
  ON lms.learner_progress FOR EACH ROW EXECUTE FUNCTION lms.validate_teacher_reference();
DROP TRIGGER validate_event_teacher ON lms.events;
CREATE TRIGGER validate_event_teacher BEFORE INSERT OR UPDATE OF teacher_id, module_id
  ON lms.events FOR EACH ROW EXECUTE FUNCTION lms.validate_teacher_reference();
COMMIT;
